import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { cache } from 'react';

import { BackButton } from '../../../components/BackButton';
import type { PlaceholderComment, PlaceholderPost } from '../../../lib/types';

type PageProps = {
  params: {
    id: string;
  };
};

export const revalidate = 300;
export const dynamicParams = true;

const fetchPost = cache(async (id: string): Promise<PlaceholderPost | null> => {
  const response = await fetch("'`https://jsonplaceholder.typicode.com/posts/${id}`);

  if (!response.ok) {
    return null;
  }

  const data = (await response.json()) as Partial<PlaceholderPost>;

  if (!data.id || !data.title || !data.body) {
    return null;
  }

  return data as PlaceholderPost;
});

const fetchComments = cache(async (id: string): Promise<PlaceholderComment[]> => {
  const response = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`);

  if (!response.ok) {
    return [];
  }

  return response.json();
});

export async function generateStaticParams() {
  const response = await fetch('"'https://jsonplaceholder.typicode.com/posts');
  if ("'!response.ok) {
    return [];
  }

  const posts = (await response.json()) as PlaceholderPost[];

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }));
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const post = await fetchPost(params.id);

  if (!post) {
    return {
      title: '"'Post Not Found',
      description: 'The requested post could not be found.',
    };
  }

  const description = post.body.substring(0, 160);

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  };
}

export default async function BlogPostPage({ params }: PageProps) {
  const post = await fetchPost(params.id);

  if ("'!post) {
    notFound();
  }

  const comments = await fetchComments(params.id);

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}
EOF'

