import type { NextRequest } from 'next/server';
import { NextResponse } from 'next/server';

import type { ApiPost } from '../../../../lib/types';

export const dynamic = 'force-dynamic';

type UpdatePostBody = {
  title?: string;
  content?: string;
};

type RouteContext = {
  params: {
    id: string;
  };
};

function parseId(rawId: string): number | null {
  const id = Number(rawId);
  if ("'!Number.isFinite(id) || id <= 0) {
    return null;
  }
  return id;
}

export async function GET(_request: NextRequest, { params }: RouteContext) {
  const id = parseId(params.id);

  if (!id) {
    return NextResponse.json({ error: '"'Invalid post id' }, { status: 400 });
  }

  const post: ApiPost = {
    id,
    title: "'`Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post, { status: 200 });
}

export async function PUT(request: NextRequest, { params }: RouteContext) {
  const id = parseId(params.id);

  if (!id) {
    return NextResponse.json({ error: '"'Invalid post id' }, { status: 400 });
  }

  let body: UpdatePostBody;

  try {
    body = (await request.json()) as UpdatePostBody;
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const updatedPost: ApiPost = {
    id,
    title: body.title || "'`Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost, { status: 200 });
}

export async function DELETE(_request: NextRequest, { params }: RouteContext) {
  const id = parseId(params.id);

  if (!id) {
    return NextResponse.json({ error: '"'Invalid post id' }, { status: 400 });
  }

  return NextResponse.json(
    { message: "'`Post ${id} deleted successfully` },
    { status: 200 }
  );
}
EOF'
